#define PI 3.14159265358979

// integer hash copied from Hugo Elias
float hash( int n ) 
{

	n = (n << 13) ^ n;

    n = n * (n * n * 15731 + 789221) + 1376312589;

    return -1.0+2.0*float( n & ivec3(0x0fffffff))/float(0x0fffffff);

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec2 uv = (fragCoord - iResolution.xy/2.)/iResolution.xx;

    vec3 col = 0.5 + 0.5*cos(iTime+uv.xyx+vec3(0,2,4));

    float loopLength = 7.7;

    float loopTime = mod(iTime, loopLength);

    float scale = 1.+pow(loopTime,loopTime*2.);

    float theta = loopTime*PI/loopLength;

    float theta2 = theta + 2.*PI/3.;

    float theta3 = theta2 + 2.*PI/3.;

    float r = hash(int(floor((uv.x*cos(theta)+uv.y*sin(theta))*scale)))/2.+0.5;

    float g = hash(int(floor((uv.x*cos(theta2)+uv.y*sin(theta2))*scale)))/2.+0.5;

    float b = hash(int(floor((uv.x*cos(theta3)+uv.y*sin(theta3))*scale)))/2.+0.5;

    fragColor = vec4(r,g,b,1.0);

}
